-- SATOSHI SCRIPT'S - OBF
local __p=""
local __k="SatoshiKey26"
local __b='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
__p=string.gsub(__p,'[^'..__b..'=]','')
local __d=__p:gsub('.',function(x)
 if x=='=' then return '' end
 local r,f='',(__b:find(x)-1)
 for i=6,1,-1 do r=r..(f%2^i-f%2^(i-1)>0 and '1' or '0') end
 return r
end):gsub('%d%d%d?%d?%d?%d?%d?%d?',function(x)
 if #x~=8 then return '' end
 local c=0
 for i=1,8 do c=c+(x:sub(i,i)=='1' and 2^(8-i) or 0) end
 return string.char(c)
end)
local __o={}
for i=1,#__d do
 local a=string.byte(__d,i)
 local b=string.byte(__k,((i-1)%#__k)+1)
 __o[i]=string.char(bit32.bxor(a,b))
end
local __s=table.concat(__o)
return loadstring(__s)()
